import re,json
S={
"game_010.md":"5:000000 6:000000 7:000000 8:000000 9:000000 25:000000 26:100000 27:000000 28:000000 29:000000 30:100000 31:100000 32:100000 33:100000 34:100000 35:001000 36:100000 37:001000 38:100000 39:100000 40:000000 41:101000 42:001000 43:101000 50:000000 51:100000 52:100000 53:100000 54:100000 55:100000 56:100000 57:100000 58:100000 59:100100 60:100000 61:100000 62:100000 63:100000 64:101000 65:101000 66:101000 67:101000 68:101000",
"game_011.md":"5:000000 6:000000 7:000000 8:000000 9:000000 25:000000 26:100000 27:000000 28:000000 29:000000 30:100000 31:100000 32:100000 33:100000 34:100000 35:100000 36:100100 37:000000 38:101000 39:100000 50:000000 51:100000 52:100000 53:100000 54:100000 55:100000 56:100000 57:100000 58:101000 59:101000",
"game_012.md":"5:000000 6:100000 7:000000 8:000000 9:000000 25:000000 26:000000 27:000000 28:000000 29:000000 30:100000 31:100000 32:100000 33:100000 34:100100 35:100000 36:110000 37:110000 38:000000 39:100000 50:000000 51:100000 52:100000 53:100000 54:100000 55:100000 56:100000 57:100000 58:100000 59:100000 60:101000 61:001000 62:100000 63:101000 64:101000"}
notes={("game_010.md",59):"does not answer Kenji's [57]",("game_011.md",36):"ignores Mio's [33]",("game_012.md",34):"ignores George's [32]"}
b="/tmp/claude-1091/-diskthalys-ssd14ta-yharada-aiwolf-undergraduate-research/bcec8730-29c9-4bd2-98fc-0a8842b00e36/scratchpad/annot8/"
out={}
for f,s in S.items():
    d={int(k):v for k,v in (x.split(":") for x in s.split())}
    sp={int(m.group(1)):m.group(2) for m in re.finditer(r"^- \[(\d+)\] \*\*(\w+)\*\*",open(b+"games/"+f).read(),re.M)}
    assert set(sp)==set(d),(f,set(sp)^set(d))
    L=[]
    for q in sorted(sp):
        v=list(map(int,d[q]))
        L.append(dict(seq=q,speaker=sp[q],resp=v[0],rebut=v[1],empty=v[2],ignore=v[3],misattr=v[4],reversal=v[5],note=notes.get((f,q),"")))
    out[f]=L
json.dump(out,open(b+"out/sonnet_03.json","w"),ensure_ascii=False)
